#include "data/Database.h"

#include <sqlite3.h>

#include "SchemaSql.h"  // generated by CMake from database/schema.sql

namespace lms::data {

// ---- Statement ---------------------------------------------------------------

Statement::Statement(sqlite3* db, const std::string& sql) : db_(db) {
    if (sqlite3_prepare_v2(db_, sql.c_str(), -1, &stmt_, nullptr) != SQLITE_OK)
        throw DatabaseError(std::string("SQL error: ") + sqlite3_errmsg(db_));
}

Statement::Statement(Statement&& other) noexcept : db_(other.db_), stmt_(other.stmt_) { other.stmt_ = nullptr; }

Statement::~Statement() { sqlite3_finalize(stmt_); }

void Statement::check(int rc) const {
    if (rc != SQLITE_OK) throw DatabaseError(std::string("SQL error: ") + sqlite3_errmsg(db_));
}

Statement& Statement::bindInt(int index, long long value) {
    check(sqlite3_bind_int64(stmt_, index, value));
    return *this;
}

Statement& Statement::bindDouble(int index, double value) {
    check(sqlite3_bind_double(stmt_, index, value));
    return *this;
}

Statement& Statement::bindText(int index, const std::string& value) {
    check(sqlite3_bind_text(stmt_, index, value.c_str(), static_cast<int>(value.size()), SQLITE_TRANSIENT));
    return *this;
}

Statement& Statement::bindNull(int index) {
    check(sqlite3_bind_null(stmt_, index));
    return *this;
}

Statement& Statement::bindOptionalInt(int index, const std::optional<int>& value) {
    return value ? bindInt(index, *value) : bindNull(index);
}

Statement& Statement::bindOptionalDouble(int index, const std::optional<double>& value) {
    return value ? bindDouble(index, *value) : bindNull(index);
}

bool Statement::step() {
    int rc = sqlite3_step(stmt_);
    if (rc == SQLITE_ROW) return true;
    if (rc == SQLITE_DONE) return false;
    throw DatabaseError(std::string("Database error: ") + sqlite3_errmsg(db_));
}

void Statement::run() {
    while (step()) {
    }
}

int Statement::columnInt(int col) const { return sqlite3_column_int(stmt_, col); }

double Statement::columnDouble(int col) const { return sqlite3_column_double(stmt_, col); }

std::string Statement::columnText(int col) const {
    const unsigned char* text = sqlite3_column_text(stmt_, col);
    return text ? reinterpret_cast<const char*>(text) : "";
}

bool Statement::isNull(int col) const { return sqlite3_column_type(stmt_, col) == SQLITE_NULL; }

// ---- Transaction -------------------------------------------------------------

Transaction::Transaction(Database& db) : db_(db), name_("sp" + std::to_string(db.nextSavepoint_++)) {
    db_.exec("SAVEPOINT " + name_);
}

Transaction::~Transaction() {
    if (committed_) return;
    try {
        db_.exec("ROLLBACK TO " + name_);
        db_.exec("RELEASE " + name_);
    } catch (...) {  // NOLINT(bugprone-empty-catch)
        // A destructor must not throw; the connection reports the error on the next statement.
    }
}

void Transaction::commit() {
    db_.exec("RELEASE " + name_);
    committed_ = true;
}

// ---- Database ----------------------------------------------------------------

Database::Database(const std::string& path) : path_(path) {
    if (sqlite3_open(path.c_str(), &handle_) != SQLITE_OK) {
        std::string message = handle_ ? sqlite3_errmsg(handle_) : "out of memory";
        sqlite3_close(handle_);
        throw DatabaseError("Cannot open database " + path + ": " + message);
    }
    exec("PRAGMA foreign_keys = ON");  // SQLite leaves them off by default
    createSchemaIfNew();
    upgradeSchema();
}

Database::~Database() { sqlite3_close(handle_); }

Statement Database::prepare(const std::string& sql) { return Statement(handle_, sql); }

void Database::exec(const std::string& sql) {
    char* error = nullptr;
    if (sqlite3_exec(handle_, sql.c_str(), nullptr, nullptr, &error) != SQLITE_OK) {
        std::string message = error ? error : "unknown error";
        sqlite3_free(error);
        throw DatabaseError("Database error: " + message);
    }
}

long long Database::lastInsertId() const { return sqlite3_last_insert_rowid(handle_); }

std::unique_ptr<repositories::ITransaction> Database::begin() { return std::make_unique<Transaction>(*this); }

void Database::createSchemaIfNew() {
    Statement count = prepare("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = 'users'");
    count.step();
    if (count.columnInt(0) == 0) exec(kSchemaSql);
}

void Database::upgradeSchema() {
    const std::string schema = kSchemaSql;
    std::size_t start = schema.find("-- Upgrades:");
    if (start == std::string::npos) throw DatabaseError("schema.sql has no Upgrades part");
    exec(schema.substr(start));
}

namespace {

void copyDatabase(sqlite3* from, sqlite3* to) {
    sqlite3_backup* backup = sqlite3_backup_init(to, "main", from, "main");
    if (!backup) throw DatabaseError(std::string("Backup failed: ") + sqlite3_errmsg(to));
    sqlite3_backup_step(backup, -1);
    if (sqlite3_backup_finish(backup) != SQLITE_OK)
        throw DatabaseError(std::string("Backup failed: ") + sqlite3_errmsg(to));
}

}  // namespace

void Database::backupTo(const std::string& path) {
    sqlite3* target = nullptr;
    if (sqlite3_open(path.c_str(), &target) != SQLITE_OK) {
        sqlite3_close(target);
        throw DatabaseError("Cannot create backup file " + path);
    }
    try {
        copyDatabase(handle_, target);
    } catch (...) {
        sqlite3_close(target);
        throw;
    }
    sqlite3_close(target);
}

void Database::restoreFrom(const std::string& path) {
    sqlite3* source = nullptr;
    if (sqlite3_open_v2(path.c_str(), &source, SQLITE_OPEN_READONLY, nullptr) != SQLITE_OK) {
        sqlite3_close(source);
        throw DatabaseError("Cannot open backup file " + path);
    }
    // Refuse files that are not an LMS backup, so a wrong file cannot wipe the data.
    sqlite3_stmt* check = nullptr;
    bool valid = sqlite3_prepare_v2(source, "SELECT count(*) FROM sqlite_master WHERE name = 'audit_log'", -1, &check,
                                    nullptr) == SQLITE_OK &&
                 sqlite3_step(check) == SQLITE_ROW && sqlite3_column_int(check, 0) == 1;
    sqlite3_finalize(check);
    if (!valid) {
        sqlite3_close(source);
        throw DatabaseError(path + " is not a Moderated LMS backup");
    }
    try {
        copyDatabase(source, handle_);
    } catch (...) {
        sqlite3_close(source);
        throw;
    }
    sqlite3_close(source);
    exec("PRAGMA foreign_keys = ON");
    upgradeSchema();  // a backup made by an older version gets the new tables
}

}  // namespace lms::data
